import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

import {
  OverflowError,
  ValueError,
  casefold,
  comparePy,
  pyFloat,
  pyInt,
  pyIsSpace,
  pyJsonDumps,
  pyLen,
  pySlice,
  pySplitWhitespace,
  pyStartsWithSpace,
  pyStrip,
  pyTruncate,
  type JsonValue,
} from "../src/python-compat.ts";

// Generated by tests/equivalence/generate_python_compat_golden.py under Python 3.12.
const golden = JSON.parse(
  readFileSync(new URL("./equivalence/golden/python-compat.json", import.meta.url), "utf8"),
);

type Row<I, O> = { input: I; output?: O; raises?: string };

// The TS error class for each Python exception name the golden table records.
const ERROR_CLASSES: Record<string, Function> = { ValueError, OverflowError };

// Collects every mismatching row so that one failure report shows all of them.
function mismatches<R>(rows: R[], check: (row: R) => unknown): unknown[] {
  const failures: unknown[] = [];
  for (const row of rows) {
    const problem = check(row);
    if (problem !== undefined) failures.push(problem);
  }
  return failures;
}

function expectRows<I, O>(rows: Row<I, O>[], actual: (input: I) => O): unknown[] {
  return mismatches(rows, (row) => {
    let got: O;
    try {
      got = actual(row.input);
    } catch (error) {
      const expected = row.raises ? ERROR_CLASSES[row.raises] : undefined;
      return expected && error instanceof expected ? undefined : { row, threw: String(error) };
    }
    if (row.raises) return { row, got };
    try {
      assert.deepStrictEqual(got, row.output);
      return undefined;
    } catch {
      return { row, got };
    }
  });
}

test("golden table was generated by Python 3.12", () => {
  assert.equal(golden.meta.python, "3.12");
  assert.equal(golden.meta.unicode, "15.0.0");
});

test("casefold matches Python for the sample strings", () => {
  assert.deepEqual(expectRows(golden.casefold, casefold), []);
});

test("casefold matches Python for every code point assigned in Unicode 15.0", () => {
  const changed = new Map<number, string>(golden.casefold_all.changed);
  const unassigned: [number, number][] = golden.casefold_all.unassigned_ranges;
  let rangeIndex = 0;
  const failures: unknown[] = [];
  for (let cp = 0; cp < 0x110000; cp += 1) {
    while (rangeIndex < unassigned.length && (unassigned[rangeIndex] as [number, number])[1] < cp) {
      rangeIndex += 1;
    }
    const range = unassigned[rangeIndex];
    if (range && range[0] <= cp && cp <= range[1]) continue;
    const ch = String.fromCodePoint(cp);
    const expected = changed.get(cp) ?? ch;
    const got = casefold(ch);
    if (got !== expected) failures.push({ cp: cp.toString(16), expected, got });
  }
  assert.deepEqual(failures, []);
});

test("casefold folds whole strings without the final-sigma rule", () => {
  assert.equal(casefold("ΟΔΟΣ"), "οδοσ");
  assert.equal(casefold("Straße"), "strasse");
  assert.equal(casefold("ÆØÅ"), "æøå");
});

test("pyIsSpace matches str.isspace for the samples", () => {
  assert.deepEqual(expectRows(golden.isspace, pyIsSpace), []);
});

test("pyIsSpace matches str.isspace for every code point", () => {
  const expected = new Set<number>(golden.isspace_all);
  const failures: string[] = [];
  for (let cp = 0; cp < 0x110000; cp += 1) {
    if (pyIsSpace(String.fromCodePoint(cp)) !== expected.has(cp)) failures.push(cp.toString(16));
  }
  assert.deepEqual(failures, []);
});

test("pyStrip matches str.strip()", () => {
  assert.deepEqual(expectRows(golden.strip, pyStrip), []);
});

test("pySplitWhitespace matches str.split()", () => {
  assert.deepEqual(expectRows(golden.split, pySplitWhitespace), []);
});

test("pyLen counts code points like len()", () => {
  assert.deepEqual(expectRows(golden.len, pyLen), []);
});

test("pyStartsWithSpace matches s[0].isspace()", () => {
  assert.deepEqual(expectRows(golden.starts_with_space, pyStartsWithSpace), []);
  assert.throws(() => pyStartsWithSpace(""));
});

test("pyTruncate matches text[: LIMIT - len(suffix)] + suffix", () => {
  type TruncateRow = { input: string; limit: number; suffix: string; output: string };
  const failures = mismatches(golden.truncate as TruncateRow[], (row) => {
    const got = pyTruncate(row.input, row.limit, row.suffix);
    return got === row.output ? undefined : { row, got };
  });
  assert.deepEqual(failures, []);
});

test("pySlice matches s[start:stop]", () => {
  type SliceRow = { input: string; start: number; stop: number | null; output: string };
  const failures = mismatches(golden.slice as SliceRow[], (row) => {
    const got = pySlice(row.input, row.start, row.stop ?? undefined);
    return got === row.output ? undefined : { row, got };
  });
  assert.deepEqual(failures, []);
});

test("comparePy orders strings by code point", () => {
  type CompareRow = { a: string; b: string; output: number };
  const failures = mismatches(golden.compare as CompareRow[], (row) => {
    const got = comparePy(row.a, row.b);
    return got === row.output ? undefined : { row, got };
  });
  assert.deepEqual(failures, []);
});

test("pyJsonDumps matches json.dumps byte for byte", () => {
  assert.deepEqual(expectRows(golden.json_dumps, (value: JsonValue) => pyJsonDumps(value)), []);
});

test("pyJsonDumps writes non-finite numbers as Python does", () => {
  assert.equal(pyJsonDumps([NaN, Infinity, -Infinity]), "[NaN, Infinity, -Infinity]");
});

function parseFloatRepr(text: string): number {
  if (text === "inf") return Infinity;
  if (text === "-inf") return -Infinity;
  if (text === "nan") return NaN;
  return Number(text);
}

test("pyFloat matches float(str), including what raises", () => {
  type FloatRow = { input: string; output?: string; raises?: string };
  const failures = mismatches(golden.float as FloatRow[], (row) => {
    let got: number;
    try {
      got = pyFloat(row.input);
    } catch (error) {
      if (row.raises && error instanceof ValueError) return undefined;
      return { row, threw: String(error) };
    }
    if (row.raises) return { row, got };
    return Object.is(got, parseFloatRepr(row.output as string)) ? undefined : { row, got };
  });
  assert.deepEqual(failures, []);
});

test("pyInt matches int(str), including what raises", () => {
  assert.deepEqual(expectRows(golden.int, pyInt), []);
  assert.throws(() => pyInt("x"), ValueError);
});

test("error classes carry Python's names", () => {
  assert.equal(new ValueError().name, "ValueError");
  assert.equal(new OverflowError().name, "OverflowError");
});
